def seal(check=False):
    p=OUT/'source-integrity.json'
    if check:
        old=load(p)
        bad=[name for name,value in old['sealed'].items() if not (ROOT/name).is_file() or sha(ROOT/name)!=value]
        assert not bad,bad
        b=load(OUT/'source-baseline.json')
        bad=[name for name,value in b['files'].items() if name.startswith(('docs/audit/sunfs/','docs/filesystems/sunfs/')) and name!='docs/filesystems/sunfs/sfs-5b1-native-block-contract.md' and (not (ROOT/name).is_file() or sha(ROOT/name)!=value)]
        assert not bad,bad
        import importlib.util
        spec=importlib.util.spec_from_file_location('qualification_runner',ROOT/'tools/sunfs5b1_validate.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
        for r in (OUT/'raw').glob('*/source-after.json'):
            assert m.source()==load(r), 'new/changed executable input after seal'
        current_outputs={str(q.relative_to(ROOT)) for q in OUT.rglob('*') if q.is_file() and '__pycache__' not in q.parts and q != p}
        assert current_outputs <= set(old['sealed']), 'unsealed evidence output'
        print('PASS: sealed files, executable inputs and previous SFS evidence unchanged')
        return
    required=['source-baseline.json','backend-geometry.json','backend-capabilities.json','typed-io-contract.md','request-identity.json','request-lifecycle.json','virtio-block-validation.json','usb-msc-audit.json','negative-tests.json','native-guest-matrix.json','smp-scope.json','forward-progress-review.json','regression-results.json','production-changes.json','validation-summary.json']
    assert all((OUT/name).is_file() for name in required), 'missing required deliverable'
    assert (ROOT/'docs/filesystems/sunfs/sfs-5b1-native-block-contract.md').is_file()
    labels={'PASS','PARTIAL','FAIL','BLOCKED','UNQUALIFIED','NOT_RUN'}
    assert set(load(OUT/'validation-summary.json')['gates'].values()) <= labels
    assert len(load(OUT/'negative-tests.json')['tests'])==20
    b=load(OUT/'source-baseline.json')
    prior={name:value for name,value in b['files'].items() if name.startswith(('docs/audit/sunfs/','docs/filesystems/sunfs/'))}
    bad=[name for name,value in prior.items() if not (ROOT/name).is_file() or sha(ROOT/name)!=value]
    assert not bad,bad
    runs=list((OUT/'raw').glob('*/input-integrity.json'));assert len(runs)>=2
    assert all(load(r)['status']=='PASS' for r in runs)
    snapshots=[load(r.parent/'source-after.json') for r in runs]
    assert all(row==snapshots[0] for row in snapshots),'native/hosted input mismatch'
    # Verify the current executable source/runner set against every exact run snapshot.
    import importlib.util
    spec=importlib.util.spec_from_file_location('qualification_runner',ROOT/'tools/sunfs5b1_validate.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
    assert m.source()==snapshots[0], 'final executable inputs changed'
    s=load(OUT/'validation-summary.json');s['gates']['G10']='PASS';write('validation-summary.json',s)
    names=set(snapshots[0])|set(str(q.relative_to(ROOT)) for q in OUT.rglob('*') if q.is_file() and '__pycache__' not in q.parts)|{'docs/filesystems/sunfs/sfs-5b1-native-block-contract.md'}
    names.discard(str(p.relative_to(ROOT)))
    sealed={name:sha(ROOT/name) for name in sorted(names) if (ROOT/name).is_file()}
    write('source-integrity.json',dict(status='PASS',manifest_scope='all runner inputs and all SFS5B1 deliverables excluding self; baseline independently hashes all incoming files',sealed=sealed,previous_sfs_files_verified=len(prior),input_integrity=[relative(r) for r in runs],rng_finding_preserved=b['rng_finding'],counter_seed_scope='runner0x5b1001 is scenario label only; actual hosted seeds in raw/source-inventory; native negative tuples deterministic',no_commit_no_push=True))
    print('sealed',len(sealed),'files; previous SFS files',len(prior))

